            justify-content: space-between;
            align-items: center;
            cursor: pointer;
            transition: background 0.2s;
        }

        .faq-question:hover {
            background: #414141;
        }

        .faq-icon {
            font-size: 2rem;
            font-weight: 300;
            transition: transform 0.2s;
        }

        .faq-item.active .faq-icon {
            transform: rotate(45deg);
        }

        .faq-answer {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.3s ease-out;
